-- 테셋 거시·국제 레슨 카드·퀴즈 (lesson_macro_1.sql): 명목국내총생산(210), 승수효과(804), 절약의 역설(813), 신용창조(353), 통화승수(612), 유동성 함정(428), 구축효과(805), 총수요(752), 공개시장운영(48), 자동안정화장치(467), 정책시차(513), 합리적 기대 이론(826)
-- 근거: 테셋37~68 블로그 글. 각 단어 뒤에 text/table/flow 카드와 quiz 2개(그중 lessonCheck 1개)를 붙인다.
-- 첫 카드 제목이 이미 있으면 건너뜀(다시 실행해도 중복 없음). lessonCheck가 이미 있는 단어도 건너뜀.

-- 명목국내총생산 (210)
UPDATE public.words SET visuals = COALESCE(visuals,'[]'::jsonb) || '[{"type": "text", "title": "명목 GDP와 실질 GDP", "body": "명목 GDP는 그해 가격 × 그해 생산량으로 계산해요.\n값만 올라도 숫자가 커지기 때문에, 진짜로 더 많이 만들었는지는 기준연도 가격으로 잰 실질 GDP로 봐요.\n그래서 경제 규모를 볼 땐 명목 GDP, 경제성장률을 잴 땐 실질 GDP를 써요."},
  {"type": "table", "title": "자동차로 계산해 보기", "columns": ["연도", "생산량 × 가격", "명목 GDP", "실질 GDP"], "rows": [["1년차(기준연도)", "100대 × 1,000만 원", "10억", "10억"], ["2년차", "100대 × 1,100만 원", "11억", "10억"], ["3년차", "110대 × 1,200만 원", "13.2억", "11억"]], "caption": "2년차는 값만 올라 명목만 늘었고 성장률은 0%예요. 명목 ÷ 실질 × 100이 GDP 디플레이터로, 3년차는 120이에요."},
  {"type": "quiz", "lessonCheck": true, "q": "생산량은 작년과 똑같은데 모든 물건값이 10% 올랐어요. 올해 명목 GDP와 실질 GDP는 어떻게 될까요?", "options": ["둘 다 10% 늘어난다", "명목 GDP만 10% 늘고 실질 GDP는 그대로다", "둘 다 그대로다", "실질 GDP만 10% 늘어난다"], "answer": 1, "explanation": "명목 GDP는 그해 가격으로 계산해서 값이 오른 만큼 커져요. 실질 GDP는 기준연도 가격으로 계산하니 생산량이 같으면 그대로예요."},
  {"type": "quiz", "q": "기준연도의 명목 GDP와 실질 GDP는 어떤 관계일까요?", "options": ["비교할 수 없다", "둘이 같다", "실질 GDP가 항상 더 크다", "명목 GDP가 항상 더 크다"], "answer": 1, "explanation": "기준연도에는 그해 가격과 기준연도 가격이 같으니 명목 GDP와 실질 GDP가 같아요. 그래서 GDP 디플레이터도 100이에요."}]'::jsonb
WHERE id = 210 AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"title": "명목 GDP와 실질 GDP"}]'::jsonb
  AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"type":"quiz","lessonCheck":true}]'::jsonb;

-- 승수효과 (804)
UPDATE public.words SET visuals = COALESCE(visuals,'[]'::jsonb) || '[{"type": "text", "title": "승수 = 1 ÷ (1 - 한계소비성향)", "body": "정부가 100을 쓰면 받은 사람이 80을 쓰고(한계소비성향 0.8), 그 80을 받은 사람이 64를 쓰는 식으로 이어져요.\n이렇게 모두 더하면 소득은 100 ÷ (1 - 0.8) = 500만큼 늘어요.\n한계소비성향이 클수록 돈이 더 많이 돌아 승수가 커져요."},
  {"type": "table", "title": "한계소비성향과 승수", "columns": ["한계소비성향", "승수", "정부지출 100의 효과"], "rows": [["0.5", "2", "소득 200 증가"], ["0.6", "2.5", "소득 250 증가"], ["0.8", "5", "소득 500 증가"]], "caption": "현실에서는 세금과 수입으로 새는 돈이 있어 교과서 공식보다 작게 나오기 쉬워요."},
  {"type": "text", "title": "균형재정승수는 1", "body": "세금을 100 걷어 그대로 100을 쓰면 소득은 그대로일까요?\n한계소비성향이 0.8이면 정부지출 100은 소득을 500 늘리고, 세금 100은 소비를 80 줄여 소득을 400 줄여요.\n합치면 소득이 딱 100 늘어나서 균형재정승수는 1이에요."},
  {"type": "quiz", "lessonCheck": true, "q": "한계소비성향이 0.75인 경제에서 정부가 지출을 100 늘렸어요. 세금·수입 등 다른 조건이 없다면 국민소득은 얼마나 늘까요?", "options": ["400", "75", "175", "133"], "answer": 0, "explanation": "승수는 1 ÷ (1 - 0.75) = 4예요. 정부지출 100이 소비로 이어지며 돌고 돌아 소득이 400 늘어요."},
  {"type": "quiz", "q": "승수효과가 더 커지는 경우는?", "options": ["번 돈 중 저축하는 비율이 높아질 때", "번 돈 중 소비하는 비율이 높아질 때", "수입품을 더 많이 살 때", "세율이 올라갈 때"], "answer": 1, "explanation": "한계소비성향이 클수록 다음 사람에게 넘어가는 소비가 커져 승수가 커져요. 저축·수입·세금은 돈이 새는 통로라 승수를 줄여요."}]'::jsonb
WHERE id = 804 AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"title": "승수 = 1 ÷ (1 - 한계소비성향)"}]'::jsonb
  AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"type":"quiz","lessonCheck":true}]'::jsonb;

-- 절약의 역설 (813)
UPDATE public.words SET visuals = COALESCE(visuals,'[]'::jsonb) || '[{"type": "flow", "title": "모두가 아끼면 생기는 일", "steps": ["불황에 모두가 저축↑", "소비 감소", "총지출 감소", "생산·소득 감소, 실업 증가", "결국 전체 저축도 늘지 못함"], "caption": "개인에게는 현명한 절약도 모두가 함께하면 경제 전체의 소득을 줄일 수 있어요."},
  {"type": "table", "title": "언제 잘 들어맞을까", "columns": ["상황", "절약의 역설"], "rows": [["불황이라 공장이 놀고 있을 때", "잘 맞아요"], ["저축이 투자로 잘 안 이어질 때", "잘 맞아요"], ["자본이 부족한 개발도상국", "잘 안 맞아요. 저축이 투자 재원이 돼 성장에 도움이 돼요"]], "caption": "절약의 역설은 수요가 부족한 불황기의 이야기예요."},
  {"type": "quiz", "lessonCheck": true, "q": "경기가 나쁠 때 불안해진 가계들이 한꺼번에 소비를 줄이고 저축을 늘렸어요. 절약의 역설에 따르면 어떻게 될까요?", "options": ["이자율이 내려 투자가 늘고 바로 소득이 늘어난다", "총지출이 줄어 국민소득이 줄고 전체 저축도 늘지 못할 수 있다", "물가만 오르고 소득은 변하지 않는다", "저축이 늘어난 만큼 국민소득도 늘어난다"], "answer": 1, "explanation": "모두가 소비를 줄이면 기업 매출이 줄어 생산과 소득이 줄어요. 소득이 줄면 저축할 돈도 줄어 전체 저축이 늘지 못할 수 있어요."},
  {"type": "quiz", "q": "절약의 역설이 가장 잘 들어맞는 상황은?", "options": ["불황이라 수요가 부족하고 설비가 놀고 있을 때", "자본이 부족해 저축이 곧 투자로 쓰이는 개발도상국", "완전고용 상태에서 물가가 빠르게 오를 때", "저축이 모두 곧바로 투자로 이어질 때"], "answer": 0, "explanation": "절약의 역설은 수요가 부족한 불황기에 잘 맞아요. 저축이 투자로 잘 이어지는 경제에서는 저축이 오히려 성장에 도움이 돼요."}]'::jsonb
WHERE id = 813 AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"title": "모두가 아끼면 생기는 일"}]'::jsonb
  AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"type":"quiz","lessonCheck":true}]'::jsonb;

-- 신용창조 (353)
UPDATE public.words SET visuals = COALESCE(visuals,'[]'::jsonb) || '[{"type": "text", "title": "같은 돈이 은행을 여러 번 돌아요", "body": "은행은 예금 중 지급준비금만 남기고 나머지를 대출해요.\n빌린 돈이 다시 다른 은행에 예금되고 또 대출되기를 반복하면서 예금통화가 불어나요.\n현금을 예금하기만 해서는 통화량이 늘지 않고, 다시 대출이 일어나야 늘어나요."},
  {"type": "table", "title": "지급준비율 10%일 때", "columns": ["단계", "예금", "지급준비금", "대출"], "rows": [["A", "200억", "20억", "180억 → B"], ["B", "180억", "18억", "162억 → C"], ["C", "162억", "16.2억", "145.8억 → D"], ["끝까지 합계", "2,000억", "200억", "1,800억"]], "caption": "예금 총액 = 200억 ÷ 0.1 = 2,000억이에요. 대출된 돈이 모두 다시 예금된다고 가정한 최대치예요."},
  {"type": "quiz", "lessonCheck": true, "q": "지급준비율이 20%이고 대출된 돈이 모두 다시 예금된다고 해요. 처음 100억 원이 예금되면, 처음 예금을 포함한 예금 총액은 최대 얼마가 될 수 있을까요?", "options": ["200억 원", "120억 원", "2,000억 원", "500억 원"], "answer": 3, "explanation": "최대 예금 총액은 처음 예금 ÷ 지급준비율이에요. 100억 ÷ 0.2 = 500억 원이에요."},
  {"type": "quiz", "q": "신용창조의 크기가 작아지는 경우는?", "options": ["은행이 남는 돈을 모두 대출할 때", "대출된 돈이 모두 다시 예금될 때", "지급준비율이 낮아질 때", "사람들이 대출받은 돈을 현금으로 더 많이 들고 있을 때"], "answer": 3, "explanation": "대출받은 돈을 현금으로 쥐고 있으면 은행으로 돌아오지 않아 다음 대출이 줄어요. 그만큼 예금통화가 덜 불어나요."}]'::jsonb
WHERE id = 353 AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"title": "같은 돈이 은행을 여러 번 돌아요"}]'::jsonb
  AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"type":"quiz","lessonCheck":true}]'::jsonb;

-- 통화승수 (612)
UPDATE public.words SET visuals = COALESCE(visuals,'[]'::jsonb) || '[{"type": "text", "title": "통화량 = 본원통화 × 통화승수", "body": "한국은행이 공급한 본원통화가 신용창조를 거쳐 통화량으로 몇 배 불어났는지를 나타낸 게 통화승수예요.\n현금을 들고 있는 사람이 없다면 최대 통화승수는 1 ÷ 지급준비율이에요. 지급준비율이 10%면 10배예요.\n사람들이 현금을 들고 있으면 은행으로 덜 돌아와서 실제 승수는 그보다 작아요."},
  {"type": "table", "title": "통화승수를 정하는 두 가지", "columns": ["요인", "승수가 커지려면", "이유"], "rows": [["지급준비율", "낮아야 해요", "대출할 수 있는 돈이 늘어요"], ["현금통화비율", "낮아야 해요", "은행으로 돌아와 다시 대출되는 돈이 늘어요"]], "caption": "본원통화는 씨앗 돈, 통화량은 승수만큼 불어난 돈이에요."},
  {"type": "quiz", "lessonCheck": true, "q": "경제가 불안해지자 사람들이 예금을 빼서 현금으로 들고 있기 시작했어요. 본원통화가 그대로라면 통화승수와 통화량은 어떻게 될까요?", "options": ["승수는 늘고 통화량은 줄어든다", "둘 다 변하지 않는다", "둘 다 줄어든다", "둘 다 늘어난다"], "answer": 2, "explanation": "현금통화비율이 높아지면 은행으로 돌아와 다시 대출되는 돈이 줄어 통화승수가 작아져요. 본원통화가 같으니 통화량도 줄어요."},
  {"type": "quiz", "q": "현금 보유가 없을 때 지급준비율이 5%라면 최대 통화승수는?", "options": ["95", "20", "10", "5"], "answer": 1, "explanation": "최대 통화승수는 1 ÷ 지급준비율이에요. 1 ÷ 0.05 = 20이에요."}]'::jsonb
WHERE id = 612 AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"title": "통화량 = 본원통화 × 통화승수"}]'::jsonb
  AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"type":"quiz","lessonCheck":true}]'::jsonb;

-- 유동성 함정 (428)
UPDATE public.words SET visuals = COALESCE(visuals,'[]'::jsonb) || '[{"type": "text", "title": "돈을 풀어도 쌓아 두기만 해요", "body": "이자율이 아주 낮으면 사람들은 \"이제 오를 일만 남았고 채권값은 내릴 것\"이라고 봐요.\n그래서 채권 대신 돈을 그대로 들고 있어 화폐수요곡선이 수평이 돼요. 화폐수요의 이자율 탄력성이 무한대인 상태예요.\n중앙은행이 돈을 더 풀어도 이자율이 내려가지 않아 투자와 총수요가 늘지 않아요."},
  {"type": "table", "title": "유동성 함정에서 정책 효과", "columns": ["정책", "효과", "이유"], "rows": [["통화정책", "거의 없어요", "돈을 풀어도 이자율이 더 내려가지 않아요"], ["재정정책", "커요", "정부지출이 늘어도 이자율이 오르지 않아 구축효과가 없어요"]], "caption": "금리를 0 가까이 내려도 경기가 잘 살아나지 않는 상황이 대표적인 예로 꼽혀요."},
  {"type": "quiz", "lessonCheck": true, "q": "금리가 0%에 가까운데 중앙은행이 통화량을 더 늘려도 사람들이 돈을 쌓아 두기만 해서 투자가 늘지 않아요. 이 상황은?", "options": ["신용창조", "스태그플레이션", "구축효과", "유동성 함정"], "answer": 3, "explanation": "이자율이 바닥이라 더 내려갈 여지가 없고, 풀린 돈은 그대로 보유돼요. 통화정책이 거의 효과를 내지 못하는 유동성 함정이에요."},
  {"type": "quiz", "q": "유동성 함정에서 화폐수요곡선의 모양과 이자율 탄력성은?", "options": ["우하향, 탄력성 0", "수평, 탄력성 무한대", "수직, 탄력성 0", "우상향, 탄력성 1"], "answer": 1, "explanation": "유동성 함정에서는 이자율이 조금도 내려가지 않은 채 돈을 얼마든지 들고 있으려 해요. 그래서 화폐수요곡선이 수평이고 탄력성은 무한대예요."}]'::jsonb
WHERE id = 428 AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"title": "돈을 풀어도 쌓아 두기만 해요"}]'::jsonb
  AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"type":"quiz","lessonCheck":true}]'::jsonb;

-- 구축효과 (805)
UPDATE public.words SET visuals = COALESCE(visuals,'[]'::jsonb) || '[{"type": "flow", "title": "정부지출이 민간 투자를 밀어내는 과정", "steps": ["정부지출↑, 국채 발행↑", "소득↑로 화폐수요↑, 채권값↓", "이자율↑", "민간 투자↓", "국민소득 증가폭이 줄어요"], "caption": "정부 지출의 효과 일부가 민간 지출 감소로 상쇄돼요."},
  {"type": "table", "title": "구축효과가 작아지는 조건", "columns": ["조건", "이유"], "rows": [["IS 곡선이 가파름", "투자가 이자율에 둔감해 덜 밀려나요"], ["LM 곡선이 완만함", "소득이 늘어도 이자율이 덜 올라요"], ["유동성 함정(LM 수평)", "이자율이 오르지 않아 구축효과가 없어요"]], "caption": "구축효과가 작을수록 재정정책의 효과가 커요."},
  {"type": "quiz", "lessonCheck": true, "q": "정부가 국채를 많이 발행해 지출을 늘렸더니 시장금리가 올라 기업들이 공장 증설을 미뤘어요. 이 현상은?", "options": ["피구 효과", "승수효과", "절약의 역설", "구축효과"], "answer": 3, "explanation": "정부가 돈을 빌려 쓰면서 이자율이 오르고, 그 때문에 민간 투자가 줄어든 거예요. 이를 구축효과라고 해요."},
  {"type": "quiz", "q": "구축효과가 가장 작게 나타나는 경우는?", "options": ["화폐수요가 이자율에 매우 둔감할 때", "경제가 유동성 함정에 빠져 이자율이 오르지 않을 때", "투자가 이자율에 매우 민감할 때", "정부가 국채를 시장에 대량으로 팔 때"], "answer": 1, "explanation": "구축효과는 이자율이 올라서 생겨요. 유동성 함정에서는 정부지출이 늘어도 이자율이 오르지 않아 민간 투자가 밀려나지 않아요."}]'::jsonb
WHERE id = 805 AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"title": "정부지출이 민간 투자를 밀어내는 과정"}]'::jsonb
  AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"type":"quiz","lessonCheck":true}]'::jsonb;

-- 총수요 (752)
UPDATE public.words SET visuals = COALESCE(visuals,'[]'::jsonb) || '[{"type": "text", "title": "총수요 = C + I + G + (X - M)", "body": "총수요는 가계 소비(C), 기업 투자(I), 정부지출(G), 순수출(X - M)을 합한 나라 전체의 수요예요.\n물가와 총수요의 관계를 그린 총수요(AD) 곡선은 오른쪽 아래로 내려가요."},
  {"type": "table", "title": "AD 곡선이 우하향하는 이유", "columns": ["효과", "물가가 내리면"], "rows": [["이자율 효과", "실질통화량↑ → 이자율↓ → 투자↑"], ["피구 효과(실질잔고 효과)", "가진 돈의 실질가치↑ → 소비↑"], ["경상수지 효과(순수출 효과)", "우리 물건이 상대적으로 싸져 수출↑"]]},
  {"type": "text", "title": "곡선 위 이동 vs 곡선 이동", "body": "물가가 바뀌는 건 AD 곡선 위에서 점이 움직이는 거예요.\n소비·투자·정부지출·순수출 증가, 감세, 통화량 증가는 AD 곡선 자체를 오른쪽으로 옮겨요.\n원자재값 상승은 AD가 아니라 단기 총공급(AS) 곡선을 왼쪽으로 옮겨요."},
  {"type": "quiz", "lessonCheck": true, "q": "다음 중 총수요(AD) 곡선 자체를 오른쪽으로 옮기는 것은?", "options": ["국제 원자재값 상승", "정부의 감세", "물가 하락", "기술 진보"], "answer": 1, "explanation": "감세는 가처분소득을 늘려 소비를 늘리므로 AD 곡선을 오른쪽으로 옮겨요. 물가 하락은 곡선 위 이동이고, 원자재값과 기술은 총공급 쪽 요인이에요."},
  {"type": "quiz", "q": "물가가 내리면 가진 돈의 실질가치가 올라 소비가 늘어나는 효과는?", "options": ["구축효과", "피구 효과", "경상수지 효과", "이자율 효과"], "answer": 1, "explanation": "피구 효과는 소득이 늘어서가 아니라, 이미 가진 돈으로 살 수 있는 게 많아져 소비가 느는 효과예요. 실질잔고 효과라고도 해요."}]'::jsonb
WHERE id = 752 AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"title": "총수요 = C + I + G + (X - M)"}]'::jsonb
  AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"type":"quiz","lessonCheck":true}]'::jsonb;

-- 공개시장운영 (48)
UPDATE public.words SET visuals = COALESCE(visuals,'[]'::jsonb) || '[{"type": "text", "title": "채권을 사고팔아 돈의 양을 조절해요", "body": "한국은행이 금융기관과 국채·통화안정증권·환매조건부채권(RP)을 사고팔아 시중 통화량과 금리를 조절하는 수단이에요. 교과서에서는 공개시장조작이라고도 해요.\n채권을 사면 돈이 시중으로 풀리고, 팔면 시중의 돈이 한국은행으로 거둬져요."},
  {"type": "table", "title": "매입과 매각", "columns": ["거래", "돈의 흐름", "결과"], "rows": [["한국은행이 채권 매입", "한국은행 → 시중", "통화량↑, 금리↓"], ["한국은행이 채권 매각", "시중 → 한국은행", "통화량↓, 금리↑"]], "caption": "기준금리는 7일물 RP 거래의 기준이 되는 금리예요. 통화안정증권은 한국은행이 발행해서 국공채가 아니에요."},
  {"type": "quiz", "lessonCheck": true, "q": "시중에 돈이 너무 많이 풀려 물가가 걱정돼요. 한국은행이 공개시장운영으로 할 수 있는 조치는?", "options": ["재할인율을 낮춘다", "보유한 국채를 시장에 판다", "국채를 시장에서 대량으로 사들인다", "지급준비율을 낮춘다"], "answer": 1, "explanation": "한국은행이 채권을 팔면 그 대금으로 시중 돈이 한국은행으로 들어와 통화량이 줄고 금리가 올라요. 나머지는 돈을 푸는 쪽이거나 공개시장운영이 아니에요."},
  {"type": "quiz", "q": "한국은행이 금융기관으로부터 RP를 사들이면 시중 통화량과 금리는?", "options": ["둘 다 변하지 않는다", "통화량↓, 금리↑", "통화량↑, 금리↓", "통화량↑, 금리↑"], "answer": 2, "explanation": "RP를 사들이면 그 대금이 금융기관으로 풀려 통화량이 늘고 금리가 내려가요. 반대로 RP를 팔면 돈이 거둬져요."}]'::jsonb
WHERE id = 48 AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"title": "채권을 사고팔아 돈의 양을 조절해요"}]'::jsonb
  AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"type":"quiz","lessonCheck":true}]'::jsonb;

-- 자동안정화장치 (467)
UPDATE public.words SET visuals = COALESCE(visuals,'[]'::jsonb) || '[{"type": "text", "title": "따로 결정하지 않아도 작동해요", "body": "누진세와 실업수당처럼 경기에 따라 세금과 정부지출이 저절로 바뀌어 경기 변동을 줄여 주는 장치예요.\n새로 법을 만들거나 예산을 짤 필요가 없어서 정책을 정하는 데 걸리는 시간(내부시차)이 없어요."},
  {"type": "table", "title": "호황과 불황에서", "columns": ["장치", "호황일 때", "불황일 때"], "rows": [["누진세", "세금이 소득보다 더 빨리 늘어 과열을 식혀요", "세금이 더 빨리 줄어 소비를 받쳐요"], ["실업수당", "지급이 줄어요", "지급이 늘어 소득 감소를 줄여요"]]},
  {"type": "quiz", "lessonCheck": true, "q": "불황으로 실직자가 늘자, 새 법이나 추가 예산 없이도 실업급여 지급액이 저절로 늘어 소비 감소를 줄였어요. 이 역할을 하는 것은?", "options": ["공개시장운영", "재량적 재정정책", "자동안정화장치", "구축효과"], "answer": 2, "explanation": "실업수당과 누진세는 경기에 따라 저절로 지출과 세금이 바뀌어 경기 변동을 줄여요. 그래서 자동안정화장치라고 해요."},
  {"type": "quiz", "q": "다음 중 자동안정화장치에 해당하는 것은?", "options": ["불황 때 국회가 새로 통과시킨 추가경정예산", "정부의 도로 건설 확대 결정", "한국은행의 기준금리 인하", "누진적인 소득세"], "answer": 3, "explanation": "누진세는 소득이 늘면 세금이 더 빨리 늘고 소득이 줄면 더 빨리 줄어 저절로 경기를 완화해요. 나머지는 정부나 한국은행이 따로 결정해야 하는 정책이에요."}]'::jsonb
WHERE id = 467 AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"title": "따로 결정하지 않아도 작동해요"}]'::jsonb
  AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"type":"quiz","lessonCheck":true}]'::jsonb;

-- 정책시차 (513)
UPDATE public.words SET visuals = COALESCE(visuals,'[]'::jsonb) || '[{"type": "text", "title": "정책은 바로 효과가 나지 않아요", "body": "경기 문제를 알아채고 정책을 정해 실행하기까지 걸리는 시간이 내부시차, 실행한 뒤 효과가 나타나기까지 걸리는 시간이 외부시차예요.\n시차가 길면 효과가 나올 때쯤 경기가 이미 바뀌어 오히려 경기 변동을 키울 수도 있어요."},
  {"type": "table", "title": "재정정책 vs 통화정책", "columns": ["구분", "내부시차", "외부시차"], "rows": [["재정정책", "길어요(예산 편성·국회 통과 필요)", "짧아요(정부지출이 바로 수요가 돼요)"], ["통화정책", "짧아요(금융통화위원회가 결정)", "길어요(금리가 투자·소비로 이어지기까지 오래 걸려요)"]], "caption": "경기를 미리 읽는 선행지표가 시차를 줄이는 데 도움이 돼요."},
  {"type": "quiz", "lessonCheck": true, "q": "정책시차에 대한 설명으로 옳은 것은?", "options": ["재정정책은 내부시차가, 통화정책은 외부시차가 길다", "재정정책은 외부시차가, 통화정책은 내부시차가 길다", "두 정책 모두 시차가 없다", "자동안정화장치는 내부시차가 가장 길다"], "answer": 0, "explanation": "재정정책은 예산과 국회를 거쳐야 해 결정이 느리지만 효과는 빨라요. 통화정책은 결정은 빠르지만 효과가 나타나기까지 오래 걸려요."},
  {"type": "quiz", "q": "한국은행이 금리를 내렸지만 기업들이 투자 계획을 바꾸고 실제로 공장을 짓기까지 1년 넘게 걸렸어요. 이 시간은?", "options": ["내부시차", "구축효과", "외부시차", "유동성 함정"], "answer": 2, "explanation": "정책을 실행한 뒤 실제 경제에 효과가 나타나기까지 걸리는 시간은 외부시차예요. 통화정책은 외부시차가 긴 편이에요."}]'::jsonb
WHERE id = 513 AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"title": "정책은 바로 효과가 나지 않아요"}]'::jsonb
  AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"type":"quiz","lessonCheck":true}]'::jsonb;

-- 합리적 기대 이론 (826)
UPDATE public.words SET visuals = COALESCE(visuals,'[]'::jsonb) || '[{"type": "text", "title": "예상된 정책은 효과가 없다", "body": "사람들은 쓸 수 있는 정보를 모두 써서 미래를 예측해요.\n정부가 돈을 풀 걸 미리 알면 물가가 오를 걸 예상해 임금과 가격을 바로 올려요. 그래서 예상된 정책은 단기에도 생산을 늘리지 못해요.\n루카스·사전트 같은 새고전학파의 주장이고, 가격과 임금이 빠르게 조정된다는 가정이 깔려 있어요."},
  {"type": "table", "title": "정책 무력성 명제", "columns": ["정책", "효과"], "rows": [["미리 예상된 정책", "임금·가격에 바로 반영돼 단기에도 효과가 없어요"], ["예상하지 못한 정책", "잠깐 효과가 있지만 곧 사라져요"]]},
  {"type": "quiz", "lessonCheck": true, "q": "합리적 기대 이론에 따르면, 중앙은행이 미리 발표한 대로 통화량을 늘릴 때 단기 생산량은?", "options": ["크게 줄어든다", "물가는 그대로이고 생산만 늘어난다", "거의 늘지 않고 물가만 오른다", "크게 늘어난다"], "answer": 2, "explanation": "사람들이 통화량 증가를 미리 알고 임금과 가격을 올리기 때문에 실질적인 변화가 없어요. 결국 물가만 오르고 생산은 거의 늘지 않아요."},
  {"type": "quiz", "q": "합리적 기대 이론에서 일시적으로라도 생산에 영향을 줄 수 있는 정책은?", "options": ["매년 같은 규칙대로 하는 정책", "이미 임금 계약에 반영된 정책", "미리 예고된 정책", "사람들이 예상하지 못한 정책"], "answer": 3, "explanation": "예상하지 못한 정책은 사람들이 미처 임금과 가격에 반영하지 못해 잠깐 효과를 내요. 하지만 곧 기대가 조정돼 효과가 사라져요."}]'::jsonb
WHERE id = 826 AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"title": "예상된 정책은 효과가 없다"}]'::jsonb
  AND NOT COALESCE(visuals,'[]'::jsonb) @> '[{"type":"quiz","lessonCheck":true}]'::jsonb;

NOTIFY pgrst, 'reload schema';

